function notice(t){$('notice').textContent=t;}
function tab(id){window.scrollTo({top:0});document.querySelectorAll('.tab').forEach(e=>e.classList.toggle('active',e.id===id));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===id));$('pageTitle').textContent=document.querySelector(`[data-tab="${id}"]`).textContent.slice(3).trim();}
