function download(name,data){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function readNum(id){const e=$(id),v=+e.value;if(!e.checkValidity()||!Number.isFinite(v))throw Error(`Проверьте параметр ${e.closest('label')?.textContent.trim()||id}`);return v;}
function params(){return{seconds:readNum('duration'),rate:readNum('rate'),side:readNum('side'),seed:readNum('seed'),event:$('event').checked,block:$('block').checked,parking:readNum('parking')};}
$('nodes').oninput=()=>{$('nOut').value=$('nodes').value;custom=false;};
$('run').onclick=async()=>{try{$('run').disabled=true;$('run').textContent='Расчёт…';notice('');await new Promise(r=>setTimeout(r,30));if(!custom)nodes=network(+$('nodes').value);validate(nodes);const p=params();if(cvSource){p.rate=cvSource.rate;p.event=false;}const inputs=demand(nodes,p),start=performance.now(),results=compare(nodes,inputs,p);report={schema:'oqim.report.v1',createdAt:new Date().toISOString(),source:cvSource?{type:'video-measured-rate',measurement:cvSource,assumptions:'Измеренная средняя интенсивность J1; пуассоновские прибытия, остальные входы и сеть сценарные.'}:{type:'synthetic',method:'Seeded Poisson arrivals with optional scheduled event'},network:nodes,parameters:p,inputs,results,runtimeMs:performance.now()-start,userAgent:navigator.userAgent};frameIndex=0;$('timeline').max=results[0].frames.length-1;$('timeline').value=0;render();saveHistory();notice(`Расчёт завершён за ${num(report.runtimeMs/1000,2)} с. Источник: ${cvSource?'измерение видео + моделирование':'синтетический сценарий'}.`);}catch(e){notice(e.message);}finally{$('run').disabled=false;$('run').textContent='Рассчитать три режима ↗';}};
function render(){if(!report)return;$('sensitivity').disabled=!report.source.measurement?.flow;$('sensitivityOutput').textContent='';const [f,r,p]=report.results,gain=f.metrics.delay?100*(f.metrics.delay-p.metrics.delay)/f.metrics.delay:0;$('statDemand').textContent=num(p.metrics.generated,1);$('statDelay').textContent=num(p.metrics.meanDelay,1)+' с';$('statGain').textContent=(gain>0?'−':gain<0?'+':'')+num(Math.abs(gain),1)+'%';$('statGain').style.color=gain>=0?'var(--green)':'var(--red)';$('statDone').textContent=num(p.metrics.completed,1);$('sourceBadge').textContent=cvSource?'Поток из видео + симуляция':'Синтетический сценарий';$('resultsBody').innerHTML=report.results.map(x=>`<tr><td>${names[x.mode]}</td>${['delay','meanDelay','maxQueue','completed','remaining','overload'].map(k=>`<td>${num(x.metrics[k],1)}</td>`).join('')}</tr>`).join('');$('resultSummary').textContent=`OQIM ${gain>=0?'снизил':'увеличил'} суммарную задержку на ${num(Math.abs(gain),1)}% относительно фиксированного режима на этом сценарии. Погрешность сохранения потока: ${p.metrics.conservationError.toExponential(2)} машин. Время расчёта: ${num(report.runtimeMs,0)} мс.`;$('recommendations').innerHTML=p.decisions.length?p.decisions.slice(-6).map(d=>`<div class="recommendation"><strong>${time(d.time)} · ${escape(d.node)}</strong> Основной зелёный ${d.from} → ${d.to} с.<br><span>${d.reason} Применение на следующей границе цикла узла.</span></div>`).join(''):'Допустимое улучшение фаз не найдено. Сохранён базовый план.';draw();chart();}
function positions(){const n=nodes.length,cols=Math.min(4,n);return nodes.map((_,i)=>({x:125+(i%cols)*(850/Math.max(1,cols-1)),y:n<=4?235:95+Math.floor(i/cols)*(290/Math.max(1,Math.ceil(n/cols)-1))}));}
function draw(){const c=$('map'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#15212c';for(let x=0;x<c.width;x+=26)for(let y=0;y<c.height;y+=26)ctx.fillRect(x,y,1,1);const ps=positions(),result=report?.results.find(r=>r.mode===$('viewMode').value),frame=result?.frames[frameIndex];ctx.font='13px Manrope, sans-serif';for(let i=0;i<nodes.length;i++){const p=ps[i],j=nodes.findIndex(n=>n.id===nodes[i].next);if(j>=0){const q=ps[j];ctx.strokeStyle='#273846';ctx.lineWidth=36;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.strokeStyle='#607080';ctx.lineWidth=1;ctx.setLineDash([7,8]);ctx.stroke();ctx.setLineDash([]);const tr=frame?.nodes[j].transit||0;for(let k=0;k<Math.min(14,Math.ceil(tr));k++){const f=(k+1)/(Math.min(14,Math.ceil(tr))+1);ctx.fillStyle='#70e4b7';ctx.fillRect(p.x+(q.x-p.x)*f-4,p.y+(q.y-p.y)*f+4,9,5);}}}
for(let i=0;i<nodes.length;i++){const p=ps[i],s=frame?.nodes[i],ratio=(s?.q||0)/nodes[i].capacity;ctx.fillStyle='#273846';ctx.fillRect(p.x-15,p.y-55,30,110);ctx.fillStyle=ratio>.9?'#ef7883':ratio>.4?'#edb96a':'#70e4b7';ctx.beginPath();ctx.arc(p.x,p.y,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='#0d151d';ctx.font='bold 13px Manrope,sans-serif';ctx.textAlign='center';ctx.fillText(nodes[i].id.slice(0,8),p.x,p.y+5);ctx.fillStyle='#dce7f0';ctx.font='12px Manrope,sans-serif';ctx.fillText(`Очередь ${num(s?.q||0,1)} / ${nodes[i].capacity}`,p.x,p.y+82);ctx.fillStyle='#8297a7';ctx.fillText(`Боковая ${num(s?.side||0,1)} · вход ${num(s?.outside||0,1)}`,p.x,p.y+101);ctx.fillStyle=s?.phase==='main'?'#70e4b7':s?.phase==='yellow'?'#edb96a':'#ef7883';ctx.beginPath();ctx.arc(p.x+34,p.y-32,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9db0bf';ctx.fillText(`Основной: ${s?.green||25} с`,p.x,p.y-67);for(let k=0;k<Math.min(12,Math.ceil(s?.q||0));k++){ctx.fillStyle=ratio>.9?'#ef7883':'#edb96a';ctx.fillRect(p.x-40-(k%6)*8,p.y-10+Math.floor(k/6)*8,6,4);}}ctx.textAlign='left';$('time').textContent=time(frame?.t||0);}
$('map').onclick=e=>{const rect=$('map').getBoundingClientRect(),x=(e.clientX-rect.left)*1100/rect.width,y=(e.clientY-rect.top)*470/rect.height,ps=positions();let nearest=0;for(let i=1;i<ps.length;i++)if(Math.hypot(x-ps[i].x,y-ps[i].y)<Math.hypot(x-ps[nearest].x,y-ps[nearest].y))nearest=i;const n=nodes[nearest],s=report?.results.find(r=>r.mode===$('viewMode').value)?.frames[frameIndex].nodes[nearest];$('nodeDetail').textContent=`${n.id}: вместимость ${n.capacity} машин; время входящего проезда ${n.travel} с; смещение ${n.offset} с; основной зелёный ${s?.green||25} с; боковой зелёный ${50-(s?.green||25)} с. Источник состояния: симуляция. Следующий узел: ${n.next||'выход из сети'}.`;};
function chart(){const c=$('chart'),ctx=c.getContext('2d');ctx.clearRect(0,0,600,230);if(!report)return;const max=Math.max(1,...report.results.map(r=>r.metrics.delay));ctx.font='11px sans-serif';for(let i=0;i<5;i++){const y=190-i*40;ctx.strokeStyle='#24313e';ctx.beginPath();ctx.moveTo(55,y);ctx.lineTo(580,y);ctx.stroke();ctx.fillStyle='#91a1b0';ctx.fillText(num(max*i/4/60,0),5,y+4);}for(const r of report.results){ctx.strokeStyle=colors[r.mode];ctx.lineWidth=2;ctx.beginPath();r.frames.forEach((f,i)=>{const x=55+i/(r.frames.length-1)*525,y=190-f.delay/max*160;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}ctx.fillStyle='#91a1b0';ctx.fillText('маш·мин',5,15);ctx.fillText('0',55,217);ctx.fillText(time(report.parameters.seconds),540,217);}
$('forecastRun').onclick=()=>{if(!report)return;const mode=$('viewMode').value,at=report.results[0].frames[frameIndex].t;const f=forecast(report.network,report.inputs,mode,at,+$('forecastHorizon').value,report.parameters);report.forecast=f;$('forecastOutput').textContent=`С ${time(at)}, горизонт ${f.horizon/60} мин. `+f.risk.map(r=>`${r.node}: ${r.firstOverload===null?'переполнение не ожидается':'риск переполнения через '+r.firstOverload+' с'}, максимум очереди ${num(r.maxQueue,1)}`).join('; ')+'. Условный прогноз по среднему потоку, доверительная вероятность не калибрована.';};
$('timeline').oninput=()=>{frameIndex=+$('timeline').value;draw();};$('viewMode').onchange=draw;$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Ⅱ Пауза':'▶ Воспроизвести';};setInterval(()=>{if(playing&&report){frameIndex=(frameIndex+1)%report.results[0].frames.length;$('timeline').value=frameIndex;draw();}},150);
