function sceneBrightness(){qualityContext.drawImage(video,0,0,32,18);const pixels=qualityContext.getImageData(0,0,32,18).data;let total=0;for(let i=0;i<pixels.length;i+=4)total+=(.2126*pixels[i]+.7152*pixels[i+1]+.0722*pixels[i+2])/255;return total/(pixels.length/4);}
function script(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');const timer=setTimeout(()=>{s.remove();reject(Error('Загрузка заняла слишком долго. Попробуйте ещё раз.'));},45000);s.src=src;s.onload=()=>{clearTimeout(timer);resolve();};s.onerror=()=>{clearTimeout(timer);s.remove();reject(Error('Не удалось загрузить модель/библиотеку. Проверьте интернет.'));};document.head.append(s);});}
let modelType='yolo',backend='';
async function modelBytes(path,label){let cache;try{cache=await caches.open('oqim-model-v1');const saved=await cache.match(path);if(saved)return new Uint8Array(await saved.arrayBuffer());}catch{}const r=await fetch(path,{signal:AbortSignal.timeout(600000)});if(!r.ok)throw Error(`${label}: HTTP ${r.status}`);const reader=r.body.getReader(),chunks=[];let received=0;while(true){const {done,value}=await reader.read();if(done)break;chunks.push(value);received+=value.length;$('cvStatus').textContent=`Загрузка ${label}: ${(received/1000000).toFixed(1)} МБ. При первом запуске суммарно около 46 МБ.`;}const bytes=new Uint8Array(received);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}try{await cache?.put(path,new Response(bytes));}catch{}return bytes;}

