async function setVideo(blob,name,id=null){
 if(blob.size>250*1024*1024)throw Error('Для браузерного демо выберите видео до 250 МБ или короткий фрагмент.');
 if(videoUrl)URL.revokeObjectURL(videoUrl);sampleId=id;clearMeasurement();
 const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),v=>v.toString(16).padStart(2,'0')).join('');
 videoIdentity={name,sha256:hash,bytes:blob.size,sampleId:id};videoUrl=URL.createObjectURL(blob);video.src=videoUrl;$('analyze').disabled=!model;
}
const samples={day:{path:'./samples/day.mp4',line:55,start:0,end:100,anchor:'centre'},night:{path:'./samples/night-wet.mp4',line:75,start:0,end:100,anchor:'centre'},motorway:{path:'./samples/motorway-a40.mp4',line:80,start:6,end:46,anchor:'bottom'}};
async function sample(id){if(running)return;try{const cfg=samples[id],r=await fetch(cfg.path);if(!r.ok)throw Error('Не удалось загрузить пример');await setVideo(await r.blob(),cfg.path,id);$('line').value=cfg.line;$('gateStart').value=cfg.start;$('gateEnd').value=cfg.end;$('anchor').value=cfg.anchor;$('flowDirection').value='down';$('cvStatus').textContent='Видео выбрано. Параметры линии установлены. Запустите анализ.';}catch(e){$('cvStatus').textContent=e.message;}}
