async function seek(t){if(Math.abs(video.currentTime-t)<0.001&&video.readyState>=2)return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(Error('Не удалось прочитать кадр видео'));},10000),cleanup=()=>{clearTimeout(timer);video.removeEventListener('seeked',done);video.removeEventListener('error',bad);},done=()=>{cleanup();resolve();},bad=()=>{cleanup();reject(Error('Ошибка декодирования видео'));};video.addEventListener('seeked',done);video.addEventListener('error',bad);video.currentTime=t;});}
function drawBoxes(boxes,tracks=[]){overlay.width=video.videoWidth;overlay.height=video.videoHeight;overlay.style.height=video.clientHeight+'px';context.clearRect(0,0,overlay.width,overlay.height);context.lineWidth=Math.max(2,overlay.width/400);context.font=`${Math.max(14,overlay.width/65)}px sans-serif`;for(const b of boxes){const [x,y,w,h]=b.bbox;context.strokeStyle='#70e4b7';context.strokeRect(x*overlay.width,y*overlay.height,w*overlay.width,h*overlay.height);context.fillStyle='#70e4b7';context.fillText(`${b.class} ${Math.round(b.score*100)}%`,x*overlay.width,Math.max(20,y*overlay.height-5));}for(const tr of tracks){context.fillStyle='#edb96a';context.beginPath();context.arc(tr.x*overlay.width,tr.anchorY*overlay.height,4,0,Math.PI*2);context.fill();}context.strokeStyle='#edb96a';context.beginPath();context.moveTo(+$('gateStart').value/100*overlay.width,+$('line').value/100*overlay.height);context.lineTo(+$('gateEnd').value/100*overlay.width,+$('line').value/100*overlay.height);context.stroke();context.fillStyle='rgba(5,15,20,.8)';context.fillRect(0,0,overlay.width*.65,48);context.font='26px sans-serif';context.fillStyle='#70e4b7';context.fillText(`${running?tracker.events.length:measurement?.total||0} пересечений · ${time(video.currentTime)}`,12,33);}
for(const id of ['line','gateStart','gateEnd','anchor','threshold'])$(id).oninput=()=>{clearMeasurement();drawBoxes([]);};
function quality(){if(!measurement||$('groundTruth').value==='')return;const gt=+$('groundTruth').value,count=measurement.total;if(!Number.isInteger(gt)||gt<0){$('quality').textContent='Эталон должен быть целым неотрицательным числом.';return;}measurement.manualReference={count:gt,absoluteError:Math.abs(gt-count),scope:'all directions within gate; same processed interval; user-entered, not independently verified'};$('measurementJSON').textContent=JSON.stringify(measurement,null,2);$('quality').textContent=`Ручной эталон: ${gt}. Модель: ${count}. Абсолютная ошибка: ${Math.abs(gt-count)}${gt>0?`; относительная: ${num(Math.abs(gt-count)/gt*100,1)}%`:''}. Это ошибка счёта, не mAP детектора.`;}
$('groundTruth').oninput=()=>{if(measurement&&$('groundTruth').value===''){delete measurement.manualReference;$('quality').textContent='Ошибка подсчёта появится после ввода эталона.';$('measurementJSON').textContent=JSON.stringify(measurement,null,2);}else quality();};
$('analyze').onclick=async()=>{if(!model||!Number.isFinite(video.duration)||video.duration<=0){$('cvStatus').textContent='Дождитесь загрузки видео.';return;}let observations,gate;try{gate={start:readNum('gateStart')/100,end:readNum('gateEnd')/100,anchor:$('anchor').value};if(gate.start>=gate.end)throw Error('Начало отрезка должно быть левее конца');observations=new Observations(validateSpaces(JSON.parse($('spaces').value||'[]')));}catch(e){$('cvStatus').textContent=e.message;return;}clearMeasurement();running=true;tracker.reset();video.pause();video.controls=false;video.scrollIntoView({block:'center'});measurement=null;for(const id of ['analyze','videoFile','line','threshold','spaces','modelChoice','sampleDay','sampleNight','sampleMotorway','gateStart','gateEnd','anchor','useCV','exportCV'])$(id).disabled=true;$('stop').disabled=false;const start=performance.now(),inference=[],diagnostics=[],brightness=[],line=+$('line').value/100,threshold=+$('threshold').value/100;let sampled=0,last=0;try{for(let frame=0;frame<Math.ceil(video.duration*10)&&running;frame++){const t=frame/10;await seek(t);if(t>.3&&Math.abs(video.currentTime-t)>.15)throw Error('Сервер не поддерживает перемотку этого видео. Загрузите файл с устройства или используйте server.py.');const clock=performance.now(),predictions=await model.detect(video,100,threshold);inference.push(performance.now()-clock);const boxes=predictions.filter(b=>['car','bus','truck','motorcycle'].includes(b.class)).map(b=>({...b,bbox:[b.bbox[0]/video.videoWidth,b.bbox[1]/video.videoHeight,b.bbox[2]/video.videoWidth,b.bbox[3]/video.videoHeight]}));const tracks=tracker.update(boxes,t,line,gate);if(sampled%10===0)brightness.push(sceneBrightness());if(sampled%10===0)diagnostics.push({time:t,boxes:boxes.map(b=>({class:b.class,score:b.score,bbox:b.bbox})),tracks:tracks.map(x=>({id:x.id,x:x.x,y:x.y}))});observations.update(tracks,t);drawBoxes(boxes,tracks);sampled++;last=t;$('cvProgress').value=Math.min(1,(t+.1)/video.duration);$('cvCounts').textContent=`Предварительно: ${tracker.events.length} пересечений. Анализ продолжается…`;$('cvStatus').textContent=`Обработано ${time(t)} / ${time(video.duration)} · ${sampled} кадров`;if(sampled%5===0)await new Promise(r=>setTimeout(r,0));}const total=Object.values(tracker.counts).reduce((a,b)=>a+b,0),duration=Math.min(video.duration,last+0.1),elapsed=(performance.now()-start)/1000;measurement={schema:'oqim.measurement.v2',video:videoIdentity,gate,sceneQuality:{meanBrightness:brightness.reduce((a,b)=>a+b,0)/Math.max(1,brightness.length),darkFrameFraction:brightness.filter(x=>x<.15).length/Math.max(1,brightness.length),method:'32x18 sRGB weighted luminance, sampled once per video second; dark threshold0.15; diagnostic, not accuracy'},createdAt:new Date().toISOString(),model:modelType==='yolo'?'YOLO26s':'COCO-SSD lite_mobilenet_v2',backend,duration,videoDuration:video.duration,complete:duration>=video.duration-0.1,sampledFrames:sampled,samplingHz:10,diagnostics,line,threshold,total,counts:tracker.counts,events:tracker.events,parking:observations.occupancy,incidents:observations.events,rate:duration?total/duration*3600:0,elapsedSeconds:elapsed,inferenceMeanMs:inference.reduce((a,b)=>a+b,0)/Math.max(1,inference.length),userAgent:navigator.userAgent};updateFlow();$('observationOutput').textContent=`Занято ${observations.occupancy.filter(x=>x.occupied).length} из ${observations.spaces.length} размеченных мест на последнем кадре. Возможных длительных остановок: ${observations.events.length}. Подробности и интервалы в JSON.`;$('measurementJSON').textContent=JSON.stringify(measurement,null,2);$('cvCounts').textContent=`Всего пересечений: ${total}. Легковые: ${tracker.counts.car}, автобусы: ${tracker.counts.bus}, грузовики: ${tracker.counts.truck}, мотоциклы: ${tracker.counts.motorcycle}. Суммарная интенсивность обоих направлений: ${num(measurement.rate,0)} машин/час.`;$('cvPerformance').textContent=`${sampled} кадров за ${num(elapsed,1)} с · ${num(sampled/elapsed,1)} кадров/с · средний inference ${num(measurement.inferenceMeanMs,1)} мс · ${num(duration,1)} с видео.`;$('cvStatus').textContent=measurement.complete?'Анализ завершён.':'Анализ остановлен. Результат только для обработанного отрезка.';$('useCV').disabled=duration<1;$('exportCV').disabled=false;quality();}catch(e){$('cvStatus').textContent=e.message;}finally{running=false;video.controls=true;for(const id of ['analyze','videoFile','line','threshold','spaces','modelChoice','sampleDay','sampleNight','sampleMotorway','gateStart','gateEnd','anchor'])$(id).disabled=false;$('stop').disabled=true;}};
function updateFlow(){if(!measurement)return;const flow=summarizeFlow(measurement,$('flowDirection').value);measurement.flow=flow;
 $('flowEstimate').textContent=`Выбрано ${flow.count} пересечений: ${num(flow.rate)} машин/ч. Приблизительный 95% интервал при пуассоновском потоке: ${num(flow.interval95[0])}–${num(flow.interval95[1])} машин/ч. ${flow.shortWindow?'Замер короче минуты: для решений нужен более длинный интервал. ':''}Интервал не учитывает ошибки детектора. ${measurement.sceneQuality?.darkFrameFraction>.5?'Тёмная сцена: вероятны пропуски, требуется ручная проверка перед использованием потока. ':''}${flow.complete?'':'Обработана только часть видео.'}`;
 $('measurementJSON').textContent=JSON.stringify(measurement,null,2);
}
$('flowDirection').onchange=updateFlow;
$('stop').onclick=()=>{running=false;};$('exportCV').onclick=()=>measurement&&download('oqim-cv-measurement.json',measurement);
$('useCV').onclick=()=>{if(!measurement)return;updateFlow();cvSource={...structuredClone(measurement),rate:measurement.flow.rate};$('rate').max=Math.max(3600,Math.ceil(cvSource.rate));$('rate').value=Math.round(cvSource.rate);$('sourceBadge').textContent='Поток из видео + симуляция';tab('network');notice(`Измеренная интенсивность (${measurement.flow.direction}) передана на вход J1. Замер ${num(measurement.duration,1)} с, ${measurement.flow.count} пересечений. Остальная сеть моделируется. Запустите расчёт.`);};
$('deviceStatus').textContent=`Вычисления: ${navigator.gpu?'WebGPU доступен для попытки запуска; предусмотрен CPU fallback':'WebGPU недоступен; YOLO будет работать на CPU, возможна низкая скорость'}. Модель загружается один раз и кэшируется браузером.`;
function showBenchmark(b){$('benchmarkSummary').innerHTML='<div class="scroll"><table><thead><tr><th>Сравнение OQIM</th><th>Среднее снижение задержки</th><th>Лучше / хуже</th><th>Худший исход</th></tr></thead><tbody>'+[['vsFixed','С фиксированным'],['vsReactive','С реактивным']].map(([key,label])=>{const r=b.summary[key];return `<tr><td>${label}</td><td>${num(r.mean,1)}%</td><td>${r.wins} / ${r.losses} из ${r.cases}</td><td>${num(r.min,1)}%</td></tr>`;}).join('')+'</tbody></table></div><p>Отрицательное снижение означает рост задержки. Все проигрыши сохранены.</p>';}
fetch('./evidence/network-benchmark.json').then(r=>r.json()).then(showBenchmark).catch(()=>{$('benchmarkSummary').textContent='Отчёт недоступен. Пересчитайте на устройстве.';});
fetch('./evidence/cv-evaluation.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(e=>{$('cvEvidence').textContent=e.displaySummary;}).catch(()=>{$('cvEvidence').textContent='Измерение готовится. Контрольный ролик можно обработать самостоятельно.';});
$('runBenchmark').onclick=()=>{$('runBenchmark').disabled=true;$('benchmarkStatus').textContent='Расчёт в отдельном потоке…';const worker=new Worker('./benchmark-worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.progress!==undefined){$('benchmarkStatus').textContent=`Обработано ${data.progress} / 120 сценариев`;return;}showBenchmark(data);$('benchmarkStatus').textContent=`Пересчитано на этом устройстве за ${num(data.runtimeMs/1000,2)} с. Все 120 исходов готовы к экспорту.`;download('oqim-recomputed-benchmark.json',data);$('runBenchmark').disabled=false;worker.terminate();};worker.onerror=()=>{$('benchmarkStatus').textContent='Браузер не выполнил расчёт. Сохранённый отчёт доступен по ссылке.';$('runBenchmark').disabled=false;worker.terminate();};worker.postMessage({run:true});};
$('sensitivity').onclick=async()=>{if(!report?.source.measurement?.flow)return;$('sensitivity').disabled=true;$('sensitivityOutput').textContent='Расчёт трёх оценок интенсивности…';await new Promise(r=>setTimeout(r,30));try{const flow=report.source.measurement.flow,rows=[flow.interval95[0],flow.rate,flow.interval95[1]].map(rate=>{const p={...report.parameters,rate,event:false};const results=compare(report.network,demand(report.network,p),p);return {rate,results:results.map(({mode,metrics})=>({mode,metrics})),gainPercent:100*(results[0].metrics.delay-results[2].metrics.delay)/Math.max(1e-12,results[0].metrics.delay)};});report.sensitivity={method:flow.intervalMethod,rows};$('sensitivityOutput').textContent=rows.map((r,i)=>`${['Нижняя','Средняя','Верхняя'][i]} оценка: ${num(r.rate)} машин/ч, снижение задержки ${num(r.gainPercent,1)}%`).join(' · ')+'. Это три сценария при неопределённом входе, не доверительный интервал эффекта. Включено в экспорт.';}catch(e){$('sensitivityOutput').textContent=e.message;}finally{$('sensitivity').disabled=false;}};
